# ==============================================================================
# 100-Day Restoration - Windows PowerShell Setup Script
# Run from the folder where you want to create the project
# Right-click PowerShell -> Run as Administrator (or set execution policy first)
# ==============================================================================

# 0. Allow script execution if needed (run once)
# Set-ExecutionPolicy -ExecutionPolicy RemoteSigned -Scope CurrentUser

Write-Host ""
Write-Host "100-Day Restoration - Project Setup" -ForegroundColor White
Write-Host "=====================================" -ForegroundColor White
Write-Host ""

# 1. Create project folder
$projectName = "restoration-100"
$root = Join-Path (Get-Location) $projectName

if (Test-Path $root) {
    Write-Host "Folder $projectName already exists. Using it." -ForegroundColor Yellow
} else {
    New-Item -ItemType Directory -Path $root | Out-Null
    Write-Host "Created folder: $root" -ForegroundColor Green
}

Set-Location $root

# 2. Create all subdirectories
Write-Host "Creating directory structure..." -ForegroundColor Cyan
$dirs = @(
    "public",
    "src",
    "src\styles",
    "src\lib",
    "src\components"
)
foreach ($d in $dirs) {
    $p = Join-Path $root $d
    if (-not (Test-Path $p)) {
        New-Item -ItemType Directory -Path $p | Out-Null
    }
}
Write-Host "Directories ready." -ForegroundColor Green

# 3. Helper function - write file from Base64
function Write-FileB64 {
    param([string]$RelPath, [string]$B64)
    $fullPath = Join-Path $root $RelPath
    $bytes = [System.Convert]::FromBase64String($B64)
    $text  = [System.Text.Encoding]::UTF8.GetString($bytes)
    Set-Content -Path $fullPath -Value $text -Encoding UTF8 -NoNewline
    Write-Host "  -> $RelPath" -ForegroundColor DarkGray
}

Write-Host "Writing source files..." -ForegroundColor Cyan
