# 4. Check Node.js
Write-Host ""
Write-Host "Checking Node.js..." -ForegroundColor Cyan
try {
    $nodeVer = node --version 2>&1
    Write-Host "Node.js found: $nodeVer" -ForegroundColor Green
} catch {
    Write-Host "Node.js NOT found." -ForegroundColor Red
    Write-Host "Download and install from: https://nodejs.org (LTS version)" -ForegroundColor Yellow
    Write-Host "Then re-run this script." -ForegroundColor Yellow
    exit 1
}

# 5. Install dependencies
Write-Host ""
Write-Host "Installing dependencies (this takes 1-2 minutes)..." -ForegroundColor Cyan
npm install
if ($LASTEXITCODE -ne 0) {
    Write-Host "npm install failed. Check your internet connection." -ForegroundColor Red
    exit 1
}
Write-Host "Dependencies installed." -ForegroundColor Green

# 6. Create .env from example
$envPath = Join-Path $root ".env"
if (-not (Test-Path $envPath)) {
    Copy-Item (Join-Path $root ".env.example") $envPath
    Write-Host ""
    Write-Host "Created .env file - YOU MUST EDIT THIS." -ForegroundColor Yellow
} else {
    Write-Host ".env already exists." -ForegroundColor DarkGray
}

# 7. Done - print next steps
